<script setup lang="ts">
/**
 * Multi-line text entry (`design/components/textarea.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/textarea.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { computed, onBeforeUnmount, onMounted, ref, watch, type Ref } from 'vue'

import { agentFill, agentMember, fitTextarea, useControlRef } from '@polymorph/vue'
import styles from '@polymorph/recipes/controls/textarea.module.css'

export type TextareaResize = NonNullable<TextareaProps['resize']>

export interface TextareaProps {
  ariaDescribedby?: string
  /**
   * Wired by FormField; set directly only when there is no visible label.
   */
  ariaLabel?: string
  /**
   * Names the field from a label elsewhere on the page, such as `SettingsRow`'s row label, which
   * is one label for a whole row rather than one per control.
   */
  ariaLabelledby?: string
  ariaRequired?: boolean
  /**
   * Native passthrough, as in Input. For surfaces that have already moved the user, such as a
   * dialog's first field. Never use it to take focus when a page loads.
   */
  autoFocus?: boolean
  /**
   * Grows with its content. Opt-in, because a field that grows while typing moves everything
   * below it, and the form decides that, not the field. Implies `resize: 'none'`, because a box
   * that resizes itself and can also be dragged would have two owners for one height.
   */
  autosize?: boolean
  /**
   * The native `<textarea>`, like Input's `controlRef`, for an application binding that must
   * read or restore a caret or selection. Merged with the autosizer's ref, so both get the same
   * node, and `null` on unmount.
   */
  controlRef?: Ref<HTMLTextAreaElement | null>
  defaultValue?: string
  disabled?: boolean
  id?: string
  invalid?: boolean
  maxLength?: number
  name?: string
  placeholder?: string
  readOnly?: boolean
  /**
   * Never horizontal, because column width belongs to the layout, not the user.
   */
  resize?: 'vertical' | 'none'
  /**
   * The height, in line units.
   */
  rows?: number
  value?: string
}

defineOptions({ name: 'Textarea', inheritAttrs: false })

const props = withDefaults(defineProps<TextareaProps>(), {
  ariaRequired: undefined,
  autoFocus: false,
  autosize: false,
  disabled: false,
  invalid: false,
  readOnly: false,
  rows: 4,
})
const emit = defineEmits<{
  blur: [event: FocusEvent]
  change: [value: string, event: Event]
  compositionEnd: [event: CompositionEvent]
  compositionStart: [event: CompositionEvent]
  focus: [event: FocusEvent]
  select: [event: Event]
}>()
const draft = ref(props.defaultValue ?? '')
const [control, attachControl] = useControlRef(() => props.controlRef)
const resizing = computed(() => props.resize ?? (props.autosize ? 'none' : 'vertical'))
const effect1 = () => {
  props.autosize && control.value && fitTextarea(control.value)
}
onMounted(effect1)
watch(() => [props.value, props.defaultValue, props.autosize], effect1, { flush: 'post' })
const effect2 = () => {
  props.autoFocus && control.value?.focus()
}
onMounted(effect2)
let release3: (() => void) | undefined
const effect3 = () => {
  release3?.()
  const ran = agentMember({
    member: 'Textarea',
    element: () => control.value,
    state: () => ({
      value: props.value ?? draft.value,
      disabled: props.disabled,
      invalid: props.invalid,
      readonly: props.readOnly,
    }),
    actions: {
      fill: {
        argument: 'text',
        run: (value) =>
          (() => {
            if (props.readOnly) throw new Error('The field is read-only.')
            agentFill(control.value, value)
          })(),
      },
      clear: () =>
        (() => {
          if (props.readOnly) throw new Error('The field is read-only.')
          agentFill(control.value, '')
        })(),
    },
  })
  release3 = () => {
    ran()
  }
}
onMounted(effect3)
onBeforeUnmount(() => release3?.())
</script>

<template>
  <textarea
    :ref="attachControl"
    :class="styles.textarea"
    :id="id"
    :rows="rows"
    :value="value ?? draft"
    :placeholder="placeholder"
    :name="name"
    :maxlength="maxLength"
    :disabled="disabled"
    :readonly="readOnly"
    :aria-label="ariaLabel"
    :aria-labelledby="ariaLabelledby"
    :aria-describedby="ariaDescribedby"
    :aria-required="ariaRequired"
    :aria-invalid="invalid ? true : undefined"
    :data-resize="resizing"
    :data-autosize="autosize ? '' : undefined"
    :data-invalid="invalid ? '' : undefined"
    :data-disabled="disabled ? '' : undefined"
    :data-readonly="readOnly ? '' : undefined"
    data-member="textarea"
    @input="
      ((draft = control?.value ?? ''),
      autosize && control && fitTextarea(control),
      emit('change', draft, $event))
    "
    @blur="emit('blur', $event)"
    @focus="emit('focus', $event)"
    @select="emit('select', $event)"
    @compositionstart="emit('compositionStart', $event)"
    @compositionend="emit('compositionEnd', $event)"
  />
</template>
